import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Landing Report: Automated Proof for Arrow Programs — Dω Generalization + Decidable Loop-Free Fragment","description":"","frontmatter":{"title":"Landing Report: Automated Proof for Arrow Programs — Dω Generalization + Decidable Loop-Free Fragment","type":"report","date":"2026-09-07T00:00:00.000Z","status_note":"Landed — `lake build` clean (24 jobs), zero `sorry`, axiom-checked."},"headers":[],"relativePath":"handl/project/reports/arrow-automated-proof-landing.md","filePath":"vendored/handl/project/reports/arrow-automated-proof-landing.md"}'),a={name:`handl/project/reports/arrow-automated-proof-landing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="landing-report-automated-proof-for-arrow-programs-—-dω-generalization-decidable-loop-free-fragment" tabindex="-1">Landing Report: Automated Proof for Arrow Programs — Dω Generalization + Decidable Loop-Free Fragment <a class="header-anchor" href="#landing-report-automated-proof-for-arrow-programs-—-dω-generalization-decidable-loop-free-fragment" aria-label="Permalink to “Landing Report: Automated Proof for Arrow Programs — Dω Generalization + Decidable Loop-Free Fragment”">​</a></h1><p><strong>Date:</strong> 2026-09-07 <strong>Scope:</strong> <code>research/arrow-calculus-kernel-poc/lean/ArrowMinimalityLib/</code></p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Two formalization milestones landed in the Lean4 corpus, both addressing the question <em>&quot;can we universalize automated proof of arrow-semantics programs?&quot;</em>:</p><ol><li><strong><code>AlgorithmicCompletenessOmega.lean</code></strong> — the invariant domain for annotation-free loop-invariant inference was widened from <code>D</code> to <code>Dω</code>, converting Theorem 4&#39;s <em>conditional</em> algorithmic completeness into an <strong>unconditional</strong> theorem.</li><li><strong><code>DecidableFragment.lean</code></strong> — the loop-free arrow fragment received a mechanized decision procedure that is <strong>sound, terminating, and complete</strong> (relative to its property language), realizing the &quot;normalize → exact semantics → TRUE/FALSE&quot; pipeline as a theorem.</li></ol><p>Both files are imported from the library root (<code>ArrowMinimalityLib.lean</code>).</p><hr><h2 id="_1-algorithmiccompletenessomega-lean-—-unconditional-completeness-in-dω" tabindex="-1">1. <code>AlgorithmicCompletenessOmega.lean</code> — unconditional completeness in Dω <a class="header-anchor" href="#_1-algorithmiccompletenessomega-lean-—-unconditional-completeness-in-dω" aria-label="Permalink to “1. AlgorithmicCompletenessOmega.lean — unconditional completeness in Dω”">​</a></h2><h3 id="the-obstruction-that-was-removed" tabindex="-1">The obstruction that was removed <a class="header-anchor" href="#the-obstruction-that-was-removed" aria-label="Permalink to “The obstruction that was removed”">​</a></h3><p><code>AlgorithmicCompleteness.lean</code> (Theorem 4) proved only <em>conditionally</em> that <code>analyze_strongest ∈ D</code>: it required D to be closed under arbitrary meets, and documented why that closure cannot be added directly — an infinitary-meet constructor forces the index type to embed <code>InvariantDomain</code> derivations (<code>Type 1</code>), so the index always lives one universe above the inductive (&quot;universe spiral&quot;).</p><h3 id="the-escape-impredicative-prop" tabindex="-1">The escape: impredicative <code>Prop</code> <a class="header-anchor" href="#the-escape-impredicative-prop" aria-label="Permalink to “The escape: impredicative Prop”">​</a></h3><p>The widened domain <code>InvariantDomainOmega</code> (<code>Dω</code>) is a <strong>Prop-valued</strong> inductive family with the same six constructors as <code>D</code> <strong>plus</strong> an infinitary-meet constructor</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>dInf : {ι : Type} → (f : ι → Val → Prop) → ((i : ι) → Dω (f i)) →</span></span>
<span class="line"><span>       Dω (fun v =&gt; ∀ i, f i v)</span></span></code></pre></div><p>Because derivations become proof-irrelevant <code>Prop</code>s, the meet&#39;s index type (the subtype of Dω-members <em>preserved by G</em>) lives in <code>Type 0</code> — the spiral does not arise.</p><h3 id="theorems-landed-all-zero-sorry" tabindex="-1">Theorems landed (all zero <code>sorry</code>) <a class="header-anchor" href="#theorems-landed-all-zero-sorry" aria-label="Permalink to “Theorems landed (all zero sorry)”">​</a></h3><table tabindex="0"><thead><tr><th>Theorem</th><th>Content</th></tr></thead><tbody><tr><td><code>domega_closed_under_meets</code></td><td>Dω closed under arbitrary meets — Theorem 4&#39;s hypothesis, now a theorem</td></tr><tr><td><code>invariant_domain_mono</code></td><td><code>D ⊆ Dω</code> — full backward compatibility</td></tr><tr><td><code>PreservesWt</code> / <code>preserves_meet</code></td><td>well-typed preservation; closed under arbitrary meets</td></tr><tr><td><code>analyze_strongest_omega_sound</code></td><td>the strongest preserved Dω-invariant is preserved</td></tr><tr><td><strong><code>analyze_strongest_omega_in_domain</code></strong></td><td><strong>headline: it is itself in Dω — Theorem 4 unconditional</strong></td></tr><tr><td><code>analyze_strongest_omega_implies_any_preserved</code></td><td>it implies every preserved Dω-invariant (so it <em>is</em> the strongest)</td></tr><tr><td><code>analyze_strongest_omega_implies_analyze_strongest</code></td><td>strictly dominates the original <code>analyze_strongest</code></td></tr><tr><td><code>domega_true_mem</code></td><td>the sound floor lives in Dω</td></tr></tbody></table><h3 id="axiom-audit" tabindex="-1">Axiom audit <a class="header-anchor" href="#axiom-audit" aria-label="Permalink to “Axiom audit”">​</a></h3><p><code>#print axioms</code> on all seven: only <code>propext</code> (standard). No <code>sorryAx</code>.</p><h3 id="honest-scope" tabindex="-1">Honest scope <a class="header-anchor" href="#honest-scope" aria-label="Permalink to “Honest scope”">​</a></h3><p>Incompleteness is <em>narrowed</em>, not eliminated: predicates outside <code>Dω</code> (e.g. iteration-count invariants not expressible via signature guarantees + meets) remain structurally undetectable. Membership in <code>Dω</code> alone does not imply preservation; soundness is stated relative to constituents&#39; preservation, matching the established framing of <code>InvariantDomain.lean</code>.</p><hr><h2 id="_2-decidablefragment-lean-—-sound-terminating-complete-decider-for-the-loop-free-fragment" tabindex="-1">2. <code>DecidableFragment.lean</code> — sound/terminating/complete decider for the loop-free fragment <a class="header-anchor" href="#_2-decidablefragment-lean-—-sound-terminating-complete-decider-for-the-loop-free-fragment" aria-label="Permalink to “2. DecidableFragment.lean — sound/terminating/complete decider for the loop-free fragment”">​</a></h2><h3 id="the-fragment" tabindex="-1">The fragment <a class="header-anchor" href="#the-fragment" aria-label="Permalink to “The fragment”">​</a></h3><p>Loop-free arrow programs over a finite domain <code>Fin n</code>:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Graph n := idG | baseG (f : Fin n → Fin n) | compG a b</span></span></code></pre></div><p>with exact semantics <code>Graph.sem : Graph n → (Fin n → Fin n)</code> by structural recursion, and a decidable property language</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>PropF n := pTrue | pEq (f : Fin n → Fin n) | pAnd p q</span></span></code></pre></div><h3 id="the-pipeline-mechanized" tabindex="-1">The pipeline, mechanized <a class="header-anchor" href="#the-pipeline-mechanized" aria-label="Permalink to “The pipeline, mechanized”">​</a></h3><p>&quot;normalize/analyze → exact semantics → prove property → TRUE/FALSE&quot; is the pair (<code>Graph.sem</code>, <code>PropF.decide</code>), backed by a finite-enumeration equality decider (<code>funEqAux</code>) whose correctness lemma <code>funEqAux_eq</code> (<code>funEqAux f g = true ↔ ∀ i, f i = g i</code>) carries soundness and completeness.</p><h3 id="the-three-guarantees-all-zero-sorry-axiom-checked" tabindex="-1">The three guarantees (all zero <code>sorry</code>, axiom-checked) <a class="header-anchor" href="#the-three-guarantees-all-zero-sorry-axiom-checked" aria-label="Permalink to “The three guarantees (all zero sorry, axiom-checked)”">​</a></h3><table tabindex="0"><thead><tr><th>Guarantee</th><th>Theorem</th><th>Axioms</th></tr></thead><tbody><tr><td><strong>Sound</strong> (TRUE → holds)</td><td><code>PropF.decider_sound</code></td><td>propext, Quot.sound</td></tr><tr><td><strong>Complete</strong> (holds → TRUE)</td><td><code>PropF.decider_complete</code></td><td>propext</td></tr><tr><td><strong>Terminating</strong> (always TRUE xor FALSE)</td><td><code>PropF.decider_terminates</code></td><td>none</td></tr></tbody></table><p>Additionally: <code>Graph.deq_true_iff</code> — semantic equality of two arrow programs is decidable; <code>funEq f g</code> yields a <code>Decidable (f = g)</code> instance via <code>decidable_of_decidable_of_iff</code>.</p><h3 id="honest-scope-the-boundaries-stated-in-file" tabindex="-1">Honest scope (the boundaries, stated in-file) <a class="header-anchor" href="#honest-scope-the-boundaries-stated-in-file" aria-label="Permalink to “Honest scope (the boundaries, stated in-file)”">​</a></h3><ul><li><strong>The <code>arr</code> restriction is mandatory, not optional</strong>: unrestricted <code>arr</code> contents = arbitrary computable functions ⇒ Rice&#39;s theorem kills any TRUE/FALSE prover even loop-free. Completeness is relative to <code>PropF</code> — the precise sense of &quot;complete for a specified class of programs/properties&quot;.</li><li><strong><code>ArrowLoop</code> is the genuine decidability boundary on infinite domains</strong> (fixpoint semantics); over finite domains it becomes model-checkable, but the one-pass structural recursion used here no longer suffices.</li><li><strong><code>first</code>/<code>second</code>/<code>fanout</code>/<code>ArrowChoice</code> are conservative extensions</strong>: products/sums of finite domains stay finite and componentwise/branchwise semantics preserve decidability. Their omission is brevity of the mechanization, not a decidability boundary (monomorphic <code>Fin n</code> encodes products by standard finite pairings).</li></ul><hr><h2 id="build-verification" tabindex="-1">Build &amp; verification <a class="header-anchor" href="#build-verification" aria-label="Permalink to “Build &amp; verification”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>cd research/arrow-calculus-kernel-poc/lean</span></span>
<span class="line"><span>lake build          # Build completed successfully (24 jobs)</span></span></code></pre></div><p>Axiom checks (all clean, no <code>sorryAx</code>):</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>#print axioms analyze_strongest_omega_in_domain                 -- [propext]</span></span>
<span class="line"><span>#print axioms analyze_strongest_omega_sound                     -- [propext]</span></span>
<span class="line"><span>#print axioms analyze_strongest_omega_implies_any_preserved     -- [propext]</span></span>
<span class="line"><span>#print axioms analyze_strongest_omega_implies_analyze_strongest -- [propext]</span></span>
<span class="line"><span>#print axioms domega_closed_under_meets                         -- [propext]</span></span>
<span class="line"><span>#print axioms invariant_domain_mono                             -- [propext]</span></span>
<span class="line"><span>#print axioms preserves_meet                                    -- (none)</span></span>
<span class="line"><span>#print axioms PropF.decider_sound                               -- [propext, Quot.sound]</span></span>
<span class="line"><span>#print axioms PropF.decider_complete                            -- [propext]</span></span>
<span class="line"><span>#print axioms PropF.decider_terminates                          -- (none)</span></span>
<span class="line"><span>#print axioms Graph.deq_true_iff                                -- [propext, Quot.sound]</span></span>
<span class="line"><span>#print axioms funEqAux_eq                                       -- [propext]</span></span></code></pre></div><p>A stale comment was also corrected en route: <code>LoopInvariantDiscovery.lean</code> line ~817 claims &quot;the hard inversions are marked <code>sorry</code>&quot; — the corpus in fact builds with <strong>zero real <code>sorry</code></strong> (verified by build + axiom check); the WP-branching-through-<code>Choice</code> section is fully proven. No source change was made to that file.</p><h2 id="files-changed" tabindex="-1">Files changed <a class="header-anchor" href="#files-changed" aria-label="Permalink to “Files changed”">​</a></h2><ul><li><strong>Added</strong> <code>lean/ArrowMinimalityLib/AlgorithmicCompletenessOmega.lean</code></li><li><strong>Added</strong> <code>lean/ArrowMinimalityLib/DecidableFragment.lean</code></li><li><strong>Modified</strong> <code>lean/ArrowMinimalityLib.lean</code> (two new imports)</li></ul><h2 id="combined-significance" tabindex="-1">Combined significance <a class="header-anchor" href="#combined-significance" aria-label="Permalink to “Combined significance”">​</a></h2><p>Together the two files give the &quot;specified class&quot; claim both halves:</p><ul><li><strong>Loop case</strong> (annotation-free inference): algorithmic completeness now unconditional within a strictly larger, unconditionally closed domain <code>Dω</code>.</li><li><strong>Loop-free case</strong>: an absolute sound/terminating/complete decision procedure for a decidable property language.</li></ul><p>The remaining boundary is exactly characterized, not hidden: outside <code>Dω</code> the inference is incomplete by theorem; beyond the decidable fragment, undecidability (Rice, fixpoints) applies — the automation claim is &quot;<em>for a proven-sound, well-characterized and now strictly widened class, automatically</em>&quot;.</p>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};